import { ActivityIndicator, Image, Modal, ScrollView, Text, TextInput, TouchableOpacity, View } from 'react-native';
import { useEffect, useState } from 'react';
import * as DocumentPicker from 'expo-document-picker';
import { Ionicons } from '@expo/vector-icons';
import { uploadPrivateDocument } from '@/lib/api/media';
import { getVendorProfile, getVendorVerification, saveVendorVerificationStep, submitVendorVerification } from '@/lib/api/vendors';

export type VendorBaseData = { business_name: string; business_phone: string; business_city: string; business_description: string; agreeToTerms: boolean };
type LocalDoc = { uri: string; mimeType?: string | null; fileSize?: number | null; fileName?: string | null } | null;
export default function VendorVerificationModal({ visible, onClose, onCreateVendor }: { visible: boolean; onClose: () => void; onCreateVendor: (data: VendorBaseData) => Promise<void> }) {
  const [step, setStep] = useState(1); const [busy, setBusy] = useState(false); const [error, setError] = useState('');
  const [base, setBase] = useState<VendorBaseData>({ business_name: '', business_phone: '', business_city: '', business_description: '', agreeToTerms: false });
  const [cnic, setCnic] = useState(''); const [front, setFront] = useState<LocalDoc>(null); const [back, setBack] = useState<LocalDoc>(null);
  const [businessType, setBusinessType] = useState('sole_proprietor'); const [businessNumber, setBusinessNumber] = useState(''); const [relationship, setRelationship] = useState('owner_director'); const [businessDoc, setBusinessDoc] = useState<LocalDoc>(null); const [letter, setLetter] = useState<LocalDoc>(null);
  const [bank, setBank] = useState(''); const [title, setTitle] = useState(''); const [account, setAccount] = useState('');
  useEffect(() => { if (!visible) return; let active = true; setError(''); void Promise.all([getVendorProfile(), getVendorVerification()]).then(([profile, verification]) => { if (!active) return; if (profile) setBase({ business_name: profile.business_name, business_phone: profile.business_phone, business_city: profile.business_city, business_description: profile.business_description || '', agreeToTerms: true }); if (!verification) { setStep(profile ? 2 : 1); return; } setBusinessType(verification.business_type || 'sole_proprietor'); setRelationship(verification.registrant_relationship || 'owner_director'); setBank(verification.payout_bank_name || ''); setTitle(verification.payout_account_title || ''); if (['under_review', 'approved'].includes(verification.status)) setStep(6); else if (!verification.cnic_last_four || verification.identity_status === 'changes_requested') setStep(2); else if (!verification.business_type || verification.business_status === 'changes_requested') setStep(3); else if (!verification.payout_bank_name || verification.payout_status === 'changes_requested') setStep(4); else setStep(5); }).catch(() => { if (active) setStep(1); }); return () => { active = false; }; }, [visible]);
  async function pickDocument(setter: (doc: LocalDoc) => void) { const result = await DocumentPicker.getDocumentAsync({ type: ['image/jpeg', 'image/png', 'image/webp', 'application/pdf'], copyToCacheDirectory: true }); if (!result.canceled) { const file = result.assets[0]; setter({ uri: file.uri, mimeType: file.mimeType || (file.name?.toLowerCase().endsWith('.pdf') ? 'application/pdf' : 'image/jpeg'), fileSize: file.size, fileName: file.name }); } }
  async function next() {
    setError(''); setBusy(true); try {
      if (step === 1) { if (!base.business_name.trim() || !base.business_phone.trim() || !base.business_city.trim() || !base.agreeToTerms) throw new Error('Complete your business details and accept the terms.'); await onCreateVendor(base); }
      if (step === 2) { if (!front || !back || cnic.replace(/\D/g, '').length !== 13) throw new Error('Enter your 13-digit CNIC and upload both sides.'); const [a, b] = await Promise.all([uploadPrivateDocument(front, 'vendor_identity_document'), uploadPrivateDocument(back, 'vendor_identity_document')]); await saveVendorVerificationStep('identity', { cnic_number: cnic, documents: [{ type: 'cnic_front', storage_key: a.key, content_type: a.content_type, original_filename: a.original_filename }, { type: 'cnic_back', storage_key: b.key, content_type: b.content_type, original_filename: b.original_filename }] }); }
      if (step === 3) { if (!businessNumber.trim() || !businessDoc || (relationship === 'authorized_representative' && !letter)) throw new Error('Add your registration number and required proof documents.'); const proof = await uploadPrivateDocument(businessDoc, 'vendor_business_document'); const docs: Record<string, string | null>[] = [{ type: 'business_registration', storage_key: proof.key, content_type: proof.content_type, original_filename: proof.original_filename }]; if (letter) { const uploaded = await uploadPrivateDocument(letter, 'vendor_authorization_document'); docs.push({ type: 'authorization_letter', storage_key: uploaded.key, content_type: uploaded.content_type, original_filename: uploaded.original_filename }); } await saveVendorVerificationStep('business', { business_type: businessType, business_number: businessNumber, registrant_relationship: relationship, documents: docs }); }
      if (step === 4) { if (!bank.trim() || !title.trim() || !account.trim()) throw new Error('Complete your payout account details.'); await saveVendorVerificationStep('payout', { bank_name: bank, account_title: title, account_number: account }); }
      if (step === 5) { await submitVendorVerification(); setStep(6); return; } setStep((value) => value + 1);
    } catch (caught) { setError(caught instanceof Error ? caught.message : 'Unable to save this step.'); } finally { setBusy(false); }
  }
  const docButton = (label: string, value: LocalDoc, set: (doc: LocalDoc) => void) => <TouchableOpacity accessibilityLabel={label} onPress={() => void pickDocument(set)} className="border border-dashed border-[#4D754D] bg-[#192219] rounded-xl p-3 mb-3 flex-row items-center"><Ionicons name={value ? 'checkmark-circle' : 'document-attach-outline'} size={22} color="#59C462" /><Text className="text-[#E5E7E1] ml-3 flex-1">{value ? `${label} selected` : `${label} (image or PDF)`}</Text>{value?.mimeType !== 'application/pdf' && <Image source={{ uri: value?.uri }} className="h-9 w-9 rounded" />}</TouchableOpacity>;
  return <Modal visible={visible} animationType="slide" onRequestClose={onClose}><View className="flex-1 bg-[#10120F]"><View className="pt-14 px-6 pb-4 flex-row items-center border-b border-[#30372B]"><View className="flex-1"><Text className="text-[#F5F5F0] text-[25px] font-bold">VENDOR VERIFICATION</Text><Text className="text-[#9BA097] text-xs mt-1">Step {Math.min(step, 5)} of 5</Text></View><TouchableOpacity disabled={busy} onPress={onClose} className="p-3"><Ionicons name="close" size={24} color="#E5E7E1" /></TouchableOpacity></View><View className="px-6 pt-4 flex-row gap-1">{[1, 2, 3, 4, 5].map((value) => <View key={value} className={`h-1.5 flex-1 rounded ${step >= value ? 'bg-[#42B84F]' : 'bg-[#30372B]'}`} />)}</View><ScrollView className="px-6 pt-6" contentContainerStyle={{ paddingBottom: 36 }} keyboardShouldPersistTaps="handled">{step === 1 && <><Title title="Business profile" note="Your phone was already verified with OTP. Add the public details players will see." /><Field label="Business name" value={base.business_name} onChangeText={(v) => setBase({ ...base, business_name: v })} /><Field label="Business phone" value={base.business_phone} keyboardType="phone-pad" onChangeText={(v) => setBase({ ...base, business_phone: v })} /><Field label="City" value={base.business_city} onChangeText={(v) => setBase({ ...base, business_city: v })} /><Field label="Description (optional)" value={base.business_description} onChangeText={(v) => setBase({ ...base, business_description: v })} /><TouchableOpacity onPress={() => setBase({ ...base, agreeToTerms: !base.agreeToTerms })} className="flex-row items-center mt-2"><Ionicons name={base.agreeToTerms ? 'checkbox' : 'square-outline'} size={22} color="#59C462" /><Text className="text-[#C9CEC4] text-xs ml-2 flex-1">I confirm this information is accurate and agree to verification.</Text></TouchableOpacity></>}{step === 2 && <><Title title="Identity verification" note="Your CNIC is fingerprinted securely. Documents are private and only visible to authorized reviewers." /><Field label="CNIC number" value={cnic} keyboardType="number-pad" onChangeText={setCnic} /><View className="mt-3">{docButton('Upload CNIC front', front, setFront)}{docButton('Upload CNIC back', back, setBack)}</View></>}{step === 3 && <><Title title="Business verification" note="Upload one registration proof. We only ask for an authorization letter when you are registering for another owner." /><Choice label="Business type" value={businessType} values={[['sole_proprietor', 'Sole proprietor'], ['partnership', 'Partnership'], ['private_limited', 'Private limited'], ['other', 'Other']]} onChange={setBusinessType} /><Field label="NTN / registration number" value={businessNumber} onChangeText={setBusinessNumber} /><Choice label="You are" value={relationship} values={[['owner_director', 'Owner / director'], ['authorized_representative', 'Authorized representative']]} onChange={setRelationship} />{docButton('Upload business registration proof', businessDoc, setBusinessDoc)}{relationship === 'authorized_representative' && docButton('Upload authorization letter', letter, setLetter)}</>}{step === 4 && <><Title title="Payout details" note="Your account number is encrypted and will only be used once payouts are enabled." /><Field label="Bank name" value={bank} onChangeText={setBank} /><Field label="Account title" value={title} onChangeText={setTitle} /><Field label="Pakistan IBAN or account number" value={account} autoCapitalize="characters" onChangeText={setAccount} /></>}{step === 5 && <><Title title="Review and submit" note="After submission, our team reviews identity, business, and payout details separately. You can add grounds after approval." /><Text className="text-[#C9CEC4] leading-5">Your documents are stored privately. We will notify you if anything needs to be corrected.</Text></>}{step === 6 && <View className="items-center py-10"><Ionicons name="checkmark-circle" size={62} color="#59C462" /><Text className="text-[#F5F5F0] text-xl font-bold mt-4">Submitted for review</Text><Text className="text-[#A5AAA1] text-center mt-2">We will review your details and let you know if changes are needed.</Text></View>}{error ? <Text className="text-[#FF8A8A] mt-4">{error}</Text> : null}{step < 6 && <TouchableOpacity disabled={busy} onPress={() => void next()} className="bg-[#42B84F] rounded-xl py-4 mt-7 items-center">{busy ? <ActivityIndicator color="#102110" /> : <Text className="text-[#102110] font-bold">{step === 5 ? 'Submit for review' : 'Save and continue'}</Text>}</TouchableOpacity>}{step === 6 && <TouchableOpacity onPress={onClose} className="bg-[#42B84F] rounded-xl py-4 mt-7 items-center"><Text className="text-[#102110] font-bold">Done</Text></TouchableOpacity>}</ScrollView></View></Modal>;
}
function Title({ title, note }: { title: string; note: string }) { return <View className="mb-5"><Text className="text-[#F5F5F0] text-xl font-bold">{title}</Text><Text className="text-[#A5AAA1] text-sm mt-1 leading-5">{note}</Text></View>; }
function Field(props: { label: string; value: string; onChangeText: (value: string) => void; keyboardType?: 'default' | 'phone-pad' | 'number-pad'; autoCapitalize?: 'none' | 'characters' }) { return <View className="mb-4"><Text className="text-[#D9DBD5] mb-1.5">{props.label}</Text><TextInput className="bg-[#1B1F19] border border-[#30372B] rounded-xl px-4 py-3 text-[#F5F5F0]" placeholderTextColor="#777D74" keyboardType={props.keyboardType} autoCapitalize={props.autoCapitalize} value={props.value} onChangeText={props.onChangeText} /></View>; }
function Choice({ label, value, values, onChange }: { label: string; value: string; values: string[][]; onChange: (value: string) => void }) { return <View className="mb-4"><Text className="text-[#D9DBD5] mb-2">{label}</Text>{values.map(([id, title]) => <TouchableOpacity key={id} onPress={() => onChange(id)} className="flex-row items-center py-2"><Ionicons name={value === id ? 'radio-button-on' : 'radio-button-off'} size={20} color="#59C462" /><Text className="text-[#E5E7E1] ml-2">{title}</Text></TouchableOpacity>)}</View>; }
